-- SELECT only. Run after apply. 예/아니오 항목은 모두 예, 그 밖의 값은 precheck의 같은 이름 항목과 같은 값이어야 한다.
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261109020000' and name='journal_memorable_pick')=1 then '예' else '아니오' end as value
union all select 'picks table RLS on, empty',case when exists(select 1 from pg_class where oid=to_regclass('public.app_journal_memorable_picks') and relrowsecurity) and not exists(select 1 from public.app_journal_memorable_picks) then '예' else '아니오' end
union all select 'picks two authenticated policies, one restrictive',case when (select count(*) from pg_policy where polrelid=to_regclass('public.app_journal_memorable_picks'))=2 and (select count(*) from pg_policy where polrelid=to_regclass('public.app_journal_memorable_picks') and not polpermissive)=1 and not exists(select 1 from pg_policy where polrelid=to_regclass('public.app_journal_memorable_picks') and not (polroles=array[to_regrole('authenticated')::oid])) then '예' else '아니오' end
union all select 'picks: no anon/service_role, no delete, value columns only',case when not has_any_column_privilege('anon','public.app_journal_memorable_picks','select,insert,update,references') and not has_table_privilege('anon','public.app_journal_memorable_picks','select,insert,update,delete') and not has_any_column_privilege('service_role','public.app_journal_memorable_picks','select,insert,update,references') and has_table_privilege('authenticated','public.app_journal_memorable_picks','select') and not has_table_privilege('authenticated','public.app_journal_memorable_picks','insert,update,delete') and has_column_privilege('authenticated','public.app_journal_memorable_picks','kind','insert,update') and has_column_privilege('authenticated','public.app_journal_memorable_picks','reason','insert,update') and not has_column_privilege('authenticated','public.app_journal_memorable_picks','memorable_id','update') and not has_column_privilege('authenticated','public.app_journal_memorable_picks','picked_at','insert') then '예' else '아니오' end
union all select 'memorable rows',(select count(*)::text from public.app_journal_memorable)
union all select 'memorable suggested rows',(select count(*)::text from public.app_journal_memorable where status='suggested')
union all select 'memorable grants policies triggers hash',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid=to_regclass('public.app_journal_memorable')),'')
  ||coalesce((select string_agg(a.attname::text||':'||coalesce(a.attacl::text,''),',' order by a.attname) from pg_attribute a where a.attrelid=to_regclass('public.app_journal_memorable') and a.attnum>0 and not a.attisdropped),'')
  ||coalesce((select string_agg(p.polname::text||p.polcmd::text||p.polpermissive::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polname) from pg_policy p where p.polrelid=to_regclass('public.app_journal_memorable')),'')
  ||coalesce((select string_agg(t.tgname::text||':'||t.tgenabled::text||':'||t.tgfoid::regproc::text,',' order by t.tgname) from pg_trigger t where t.tgrelid=to_regclass('public.app_journal_memorable') and not t.tgisinternal),''));
